const ABRAND_HIST={
  'Voisin':{city:'Бийанкур',t:'Габриэль Воизен и брат Шарль открыли в 1906 году первый в мире авиазавод. Их «этажерки» купили Фарман и Делагранж; в войну — тысячи бомбардировщиков «Вуазен», после — роскошные автомобили «Авион Вуазен».'},
  'Farman':{city:'Бийанкур',t:'Анри Фарман, велогонщик и автогонщик, в 1908 году первым в Европе пролетел километр по кругу. Братья Анри, Морис и Дик Фарман делали учебные и разведчики, в 1919 году — авиалайнер «Голиаф» и авиалинию Париж — Брюссель.'},
  'Blériot':{city:'Бюк под Парижем',t:'Луи Блерио разбогател на автомобильных фарах и потратил всё на аэропланы. 25 июля 1909 года перелетел Ла-Манш на «Блерио XI» — и получил сотню заказов. В 1914 году купил SPAD.'},
  'SPAD':{city:'Париж',t:'Арман Депердюссен строил гоночные монококи — 200 км/ч в 1913 году. Его арестовали за мошенничество; Блерио купил фирму и сохранил буквы SPAD. Истребители SPAD VII и XIII — оружие Гинемера, Фонка и Рикенбакера.'},
  'Nieuport':{city:'Иси-ле-Мулино',t:'Эдуар Ньюпор строил быстрые монопланы (рекорд скорости 1911 года), после его гибели марку вели инженеры. «Бебе» и «Ньюпор-17» — первые настоящие истребители Антанты.'},
  'Morane-Saulnier':{city:'Пюто',t:'Братья Моран и Раймон Солнье: на их монопланах Гаррос перелетел Средиземное море (1913) и первым стрелял через винт (1915).'},
  'Caudron':{city:'Ле-Кротуа',t:'Братья Рене и Гастон Кодрон: лёгкие учебные бипланы, G.3 — разведчик первых месяцев войны и учебный аэроплан тысяч пилотов.'},
  'Breguet':{city:'Велизи',t:'Луи Бреге, из династии часовщиков. «Бреге-14» из дюраля (1917) — лучший дневной бомбардировщик войны, «Бреге-19» — машина рекордных перелётов 1920-х.'},
  'Latécoère':{city:'Тулуза',t:'Пьер-Жорж Латекоэр строил вагоны, а в 1918 году открыл авиапочту Тулуза — Касабланка — Дакар — Южная Америка. На его линиях летали Мермоз и Сент-Экзюпери.'},
  'Potez':{city:'Мольт',t:'Анри Потез, однокашник Марселя Блоха: «Потез-25» (1925) — самый массовый военный самолёт 1920-х, его брали двадцать стран.'},
  'Short Brothers':{city:'Лейсдаун, Рочестер',t:'Братья Шорт шили воздушные шары, в 1909 году по лицензии Райтов собрали шесть аэропланов — первую в мире серию. Потом — гидроаэропланы и летающие лодки.'},
  'Avro':{city:'Манчестер',t:'Алиот Верден Роу (1910). Avro 504 — учебный самолёт, на котором училась летать вся Британская империя: почти 9 000 штук.'},
  'Bristol':{city:'Бристоль',t:'Сэр Джордж Уайт, трамвайный король, основал «Бристоль» в 1910 году. Бипланы-«коробки», истребитель F.2B и мотор «Юпитер».'},
  'Sopwith':{city:'Кингстон-на-Темзе',t:'Томас Сопвич, яхтсмен и авиатор, — «Таблоид» (Кубок Шнейдера 1914), «Пап», триплан и «Кэмел» — истребитель, сбивший больше всех. В 1920 году фирма закрылась из-за военного налога; из неё вышел «Хокер».'},
  'Airco / de Havilland':{city:'Хендон, Эджвер',t:'Джеффри де Хэвилленд конструировал для Airco бомбардировщики DH.4 и DH.9, в 1920 году открыл свою фирму, а в 1925-м сделал «Мот» — самолёт для аэроклубов всего мира.'},
  'Vickers':{city:'Вейбридж',t:'Оружейный концерн: первый «боевой» самолёт с пулемётом (F.B.5, 1915) и «Вими», на котором Алкок и Браун перелетели Атлантику (1919).'},
  'Handley Page':{city:'Криклвуд',t:'Фредерик Хэндли Пейдж: тяжёлые бомбардировщики O/100 и O/400, после войны — авиалайнеры и щелевое крыло.'},
  'Supermarine':{city:'Саутгемптон',t:'Летающие лодки и гоночные гидропланы Реджинальда Митчелла: S.5 и S.6 выиграли Кубок Шнейдера в 1927 и 1929 годах.'},
  'Etrich / Rumpler':{city:'Берлин-Йоханнисталь',t:'Иго Этрих построил «Таубе» — «голубку» с крылом по форме семени лианы; Эдмунд Румплер строил её по лицензии сотнями. После войны Румплер сделал каплевидный автомобиль.'},
  'Albatros':{city:'Берлин-Йоханнисталь',t:'«Альбатросы» D.I–D.V с фанерным фюзеляжем-монококом в 1917 году правили небом Западного фронта — «Кровавый апрель».'},
  'Fokker':{city:'Шверин, Амстердам',t:'Голландец Энтони Фоккер: «Паук» (1910), синхронизатор и моноплан E.I (1915) — «фоккеровский бич», триплан Dr.I Рихтгофена и лучший истребитель войны D.VII. После войны вывез самолёты в Голландию и строил авиалайнеры F.VII.'},
  'Aviatik':{city:'Мюльхаузен, Лейпциг',t:'Автомобильная фирма Георга Шопена: разведчики первых лет войны.'},
  'DFW':{city:'Лейпциг',t:'Немецкий завод разведчиков: DFW C.V (1917) — самый массовый немецкий самолёт войны.'},
  'Gotha':{city:'Гота',t:'Вагоностроительный завод: бомбардировщики «Гота» в 1917 году бомбили Лондон днём.'},
  'Junkers':{city:'Дессау',t:'Профессор Хуго Юнкерс делал газовые колонки и калориферы. В 1915 году построил J 1 — первый цельнометаллический самолёт, в 1919-м — F 13, первый металлический авиалайнер; открыл авиалинии по всему миру и завод в Филях под Москвой.'},
  'Dornier':{city:'Фридрихсхафен',t:'Клод Дорнье, инженер графа Цеппелина: металлические летающие лодки «Валь» (1922) — их строили в Италии, обходя Версаль.'},
  'Heinkel':{city:'Варнемюнде',t:'Эрнст Хейнкель (1922): гидросамолёты и почтовые самолёты — часть строили в Швеции, чтобы обойти запреты.'},
  'Caproni':{city:'Милан, Таливедо',t:'Джанни Капрони построил первый аэроплан в 1910 году; трёхмоторные бомбардировщики Ca.3 летали через Альпы бомбить Австрию.'},
  'SIA / Fiat':{city:'Турин',t:'ФИАТ делал моторы, его дочерняя SIA — разведчики; после войны — «Фиат Авиационе».'},
  'Ansaldo':{city:'Генуя',t:'Судостроители и пушкари: SVA — быстрый разведчик, на котором д’Аннунцио в 1918 году разбросал листовки над Веной.'},
  'Macchi':{city:'Варезе',t:'Каретный завод Макки: летающие лодки, гоночные M.39 и M.52 — Кубок Шнейдера 1926 года и рекорд скорости.'},
  'Savoia-Marchetti':{city:'Сесто-Календе',t:'Гидросамолёты Алессандро Маркетти: двухкорпусный S.55 летал строем через Атлантику.'},
  'Wright Company':{city:'Дейтон',t:'Уилбур и Орвилл Райт, велосипедные мастера: первый полёт 17 декабря 1903 года. Фирма (1909) больше судилась за патенты, чем строила; Уилбур умер в 1912 году, Орвилл продал фирму в 1915-м.'},
  'Curtiss':{city:'Хаммондспорт, Буффало',t:'Гленн Кёртисс: мотоциклы, «Джун Баг» (1908), Кубок Гордона Беннетта в Реймсе (1909), гидроаэропланы, «Дженни» и летающие лодки NC — первая через Атлантику (1919). Крупнейший авиазавод Америки.'},
  'Glenn L. Martin':{city:'Лос-Анджелес, Кливленд',t:'Гленн Мартин строил аэропланы в заброшенной церкви; бомбардировщики MB-1 и MB-2. У него начинали Боинг, Дуглас и Белл.'},
  'Dayton-Wright':{city:'Дейтон',t:'Военный завод автомобильных магнатов Дейтона: 3 106 бомбардировщиков DH-4 с мотором «Либерти» за 1918 год.'},
  'Boeing':{city:'Сиэтл',t:'Лесопромышленник Уильям Боинг (1916): гидросамолёты, почтовый Model 40 и своя авиапочтовая линия, истребители для армии и флота.'},
  'Douglas':{city:'Санта-Моника',t:'Дональд Дуглас: «Уорлд Крузеры» облетели вокруг света в 1924 году.'},
  'Travel Air':{city:'Уичито',t:'Уолтер Бич, Клайд Сессна и Ллойд Стирман: лёгкие бипланы для пилотов-«барнстормеров» и бума 1927–1929 годов.'},
  'Waco':{city:'Трой, Огайо',t:'Лёгкие бипланы для частных пилотов: в 1929 году «Вако» — крупнейший производитель гражданских самолётов Америки.'},
  'Ford':{city:'Дирборн',t:'Генри Форд купил металлический завод Стаута: «Форд-тримотор» («Жестяной гусь», 1926) — авиалайнер первых авиалиний Америки.'},
  'Lockheed':{city:'Бербанк',t:'Братья Локхид и конструктор Джек Нортроп: «Вега» (1927) с фюзеляжем-скорлупой — самолёт рекордов Амелии Эрхарт и Уайли Поста.'},
  '«Руссо-Балт» (Сикорский)':{city:'Петербург',t:'Авиаотдел Русско-Балтийского вагонного завода: Игорь Сикорский построил «Русского витязя» — первый в мире четырёхмоторный самолёт (1913) и «Илью Муромца».'},
  '«Дукс»':{city:'Москва',t:'Завод Юлия Меллера: велосипеды, мотоциклы, по лицензии — «Фарманы», «Ньюпоры», «Мораны». После революции — Государственный авиазавод № 1, Р-1 Поликарпова.'},
  '«Лебедь» (Лебедев)':{city:'Петербург',t:'Авиатор Владимир Лебедев собирал разведчики «Лебедь» — свои и копии трофейных «Альбатросов».'},
  '«Анатра»':{city:'Одесса',t:'Банкир Артур Анатра: разведчики «Анатра-Д» («Анаде») для фронта.'},
  'ЦАГИ (Туполев)':{city:'Москва',t:'Андрей Туполев: АНТ-2 (1924) — первый советский металлический самолёт, АНТ-3 и АНТ-9.'}};
